#!/bin/bash
# RLinear on Weather: input 96, horizons 96 192 336 720; settings of the official scripts, protocol of the official loaders.
# Generated by scripts/multivariate_forecasting/make_scripts.py: change the profile and generate again.
#   bash scripts/multivariate_forecasting/Weather/RLinear.sh                                   seeds 2021 2022 2023
#   SEEDS="2021" EXTRA_ARGS="--no_use_gpu --num_workers 0" bash scripts/multivariate_forecasting/Weather/RLinear.sh   one seed on the CPU
# Results: output/long_term_forecast/Weather.tsv (one row per run); checkpoints: temp/checkpoints/Weather/.
export CUDA_VISIBLE_DEVICES=${CUDA_VISIBLE_DEVICES:-0}
cd "$(dirname "$0")/../../.."
root="$(python -m src.utils.paths root weather.csv)/"
seeds=(${SEEDS:-2021 2022 2023})

# horizon 96: scripts/benchmark/official/RLinear/script.md
for seed in "${seeds[@]}"; do
  python -u scripts/run.py \
    --is_training 1 \
    --model RLinear \
    --des Weather_96_RLinear \
    --seed "$seed" \
    --root_path "$root" \
    --data_path weather.csv \
    --data custom \
    --model_id Weather_96_96 \
    --features M \
    --seq_len 96 \
    --label_len 48 \
    --pred_len 96 \
    --enc_in 21 \
    --dec_in 21 \
    --c_out 21 \
    --freq h \
    --drop_last \
    --test_batch_size 1 \
    --learning_rate 0.005 \
    --batch_size 128 \
    --train_epochs 15 \
    --patience 10 \
    $EXTRA_ARGS
done

